         {"name": "Unterkunft", "weight": 10, "min": 120, "max": 650, "titles": ["Ferienwohnung Mallorca", "Hotel Lissabon", "Hütte Allgäu", "Airbnb Amsterdam"], "descriptions": ["Anzahlung", "Restzahlung", "Kurtaxe"]},
         {"name": "Transport", "weight": 12, "min": 25, "max": 420, "titles": ["Flüge", "Mietwagen", "Tanken", "Zugtickets", "Fähre"], "descriptions": ["Hinreise", "Rückreise", "vor Ort"]},
         {"name": "Restaurant", "weight": 15, "min": 40, "max": 180, "titles": ["Tapas-Bar", "Fischrestaurant", "Pizzeria", "Brauhaus"], "descriptions": ["Abendessen", "Mittagessen"]},
         {"name": "Lebensmittel", "weight": 10, "min": 15, "max": 90, "titles": ["Supermarkt", "Markthalle", "Bäckerei"], "descriptions": ["Frühstück", "Vorräte", "Grillen"]},
         {"name": "Ausgehen", "weight": 8, "min": 20, "max": 120, "titles": ["Cocktailbar", "Club", "Strandbar"], "descriptions": ["Getränke", "Eintritt"]},
